function select(record: Record<string, Labels>, index: number) {
  return Object.fromEntries(Object.entries(record).map(([key, values]) => [key, values[index]]));
}

function make(index: number, core: (typeof localeCore)[keyof typeof localeCore]) {
  const sectionTitles = select(sections, index);
  const sectionDescriptions = select(descriptions, index);
  return {
    landing: { title: core.landing[0], description: core.landing[1] },
    sections: Object.fromEntries(Object.keys(sections).map((key) => [key, { title: sectionTitles[key], description: sectionDescriptions[key] }])),
    filters: { from: core.filters[0], to: core.filters[1], year: ["Anno", "Año", "Year", "Année", "Jahr", "السنة"][index], areaOperativa: core.filters[2], allAreeOperative: core.filters[3], centre: core.filters[4], allCentres: core.filters[5], warehouse: core.filters[6], allWarehouses: core.filters[7], mensa: core.filters[8], allMense: core.filters[9], zone: core.filters[10], allZones: core.filters[11] },
    unavailable: core.unavailable,
    error: core.error,
    generated: core.generated,
    empty: { title: core.empty[0], description: core.empty[1] },
    availability: { ok: "OK", derivable: index === 0 ? "Derivabile" : index === 1 ? "Derivable" : index === 2 ? "Derivable" : index === 3 ? "Dérivable" : index === 4 ? "Ableitbar" : "قابل للاشتقاق", missing: core.unavailable },
    units: { count: "", quantity: core.units[0], kg: core.units[1], credit: core.units[2], days: core.units[3], average: core.units[4] },
    chart: { primary: core.chart[0], secondary: core.chart[1] },
    kpi: select(kpi, index),
    series: select(tables, index),
    tables: select(tables, index),
    columns: select(columnNames, index),
    quality: select(quality, index),
    export: select(exportLabels, index),
    status: { ok: "OK", derivable: ["Derivabile", "Derivable", "Derivable", "Dérivable", "Ableitbar", "قابل للاشتقاق"][index], missing: ["Mancante", "Ausente", "Missing", "Manquant", "Fehlend", "مفقود"][index] },
    text: select(textLabels, index),
    definitions: { title: core.definitions },
    drilldown: { open: core.drilldown[0], title: core.drilldown[1], description: core.drilldown[2], page: core.drilldown[3], previous: core.drilldown[4], next: core.drilldown[5] },
  };
}

